Denomination?[] Jams = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];
int[] Amounts = [-10, 0, 5, .. Enumerable.Range(1, 22).Select(i => i * 10)];
int[] Balances = Enumerable.Range(0, 51).Select(i => i * 5).ToArray();
int[] Withdrawns = Enumerable.Range(0, 21).Select(i => i * 10).ToArray();
IEnumerable<NoteCounts> AllStocks() { for (var f = 0; f <= 5; f++) for (var t = 0; t <= 5; t++) for (var c = 0; c <= 5; c++) yield return new(f, t, c); }
NoteCounts[] Deps = Enumerable.Range(0,8).Select(m => new NoteCounts(m&1,(m>>1)&1,(m>>2)&1)).ToArray();
NoteCounts Usable(NoteCounts s, Denomination? j) => new(j==Denomination.Fifty?0:s.Fifties, j==Denomination.Twenty?0:s.Twenties, j==Denomination.Ten?0:s.Tens);
NoteCounts? Fewest(int amount, NoteCounts u) { NoteCounts? b=null; for (int f=0;f<=u.Fifties;f++) for(int t=0;t<=u.Twenties;t++) for(int c=0;c<=u.Tens;c++){var n=new NoteCounts(f,t,c); if(n.Value==amount && (b is not {} x || n.Total<x.Total)) b=n;} return b; }
AtmResult ExpW(AccountState a, NoteCounts s, Denomination? j, int amount) {
  AtmResult R(AtmStatus st) => new(st, NoteCounts.None, 0, a);
  if (amount <= 0 || amount % 10 != 0) return R(AtmStatus.InvalidAmount);
  if (a.WithdrawnToday + amount > 200) return R(AtmStatus.DailyLimitExceeded);
  var fee = amount > 100 ? 5 : 0;
  if (amount + fee > a.Balance) return R(AtmStatus.InsufficientFunds);
  if (Fewest(amount, Usable(s,j)) is not {} n) return R(AtmStatus.CannotDispense);
  return new(AtmStatus.Ok, n, fee, new(a.Balance-amount-fee, a.WithdrawnToday+amount));
}
AtmResult ExpD(AccountState a, NoteCounts s, Denomination? j, NoteCounts n) {
  AtmResult R(AtmStatus st) => new(st, NoteCounts.None, 0, a);
  if (n.Total == 0) return R(AtmStatus.InvalidAmount);
  if (j is {} jj && n.Of(jj) > 0) return R(AtmStatus.CassetteJammed);
  var af = s + n; if (af.Fifties>5||af.Twenties>5||af.Tens>5) return R(AtmStatus.CassetteFull);
  return new(AtmStatus.Ok, NoteCounts.None, 0, a with { Balance = a.Balance + n.Value });
}
long wd=0, wdiff=0, dd=0, ddiff=0; var samples = new List<string>();
foreach (var s in AllStocks()) foreach (var j in Jams) foreach (var b in Balances) foreach (var w in Withdrawns) {
  var acc = new AccountState(b, w);
  foreach (var am in Amounts) { wd++; var m = new MoneyDispenser(s, j); var r = new CashMachine(m).Execute(acc, new Operation.Withdraw(am)); var e = ExpW(acc, s, j, am);
