  foreach (var n in Deps) { dd++; var m = new MoneyDispenser(s, j); var r = new CashMachine(m).Execute(acc, new Operation.Deposit(n)); var e = ExpD(acc, s, j, n);
    if (r != e || m.Stock != (e.Status==AtmStatus.Ok ? s + n : s)) { ddiff++; if (samples.Count < 15) samples.Add($"D {acc} {s} {j} {n}: got {r} exp {e}"); } }
}
Console.WriteLine($"withdraw {wdiff}/{wd}  deposit {ddiff}/{dd}");
samples.ForEach(Console.WriteLine);
