using Atm;
Denomination?[] Jams = [null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten];
int[] Amounts = [-10, 0, 5, .. Enumerable.Range(1, 22).Select(i => i * 10)];
int[] Balances = Enumerable.Range(0, 51).Select(i => i * 5).ToArray();
int[] Withdrawns = Enumerable.Range(0, 21).Select(i => i * 10).ToArray();
IEnumerable<NoteCounts> AllStocks() { for (var f = 0; f <= 5; f++) for (var t = 0; t <= 5; t++) for (var c = 0; c <= 5; c++) yield return new(f, t, c); }
NoteCounts[] Deps = Enumerable.Range(0,8).Select(m => new NoteCounts(m&1,(m>>1)&1,(m>>2)&1)).ToArray();
NoteCounts Usable(NoteCounts s, Denomination? j) => new(j==Denomination.Fifty?0:s.Fifties, j==Denomination.Twenty?0:s.Twenties, j==Denomination.Ten?0:s.Tens);
NoteCounts? Fewest(int amount, NoteCounts u) { if (amount<=0||amount%10!=0) return null; NoteCounts? b=null; for (int f=0;f<=u.Fifties;f++) for(int t=0;t<=u.Twenties;t++) for(int c=0;c<=u.Tens;c++){var n=new NoteCounts(f,t,c); if(n.Value==amount && (b is not {} x || n.Total<x.Total)) b=n;} return b; }
int Key(int b,int w,NoteCounts s,Denomination? j,int a) => ((((b/5)*21 + w/10)*216 + s.Fifties*36+s.Twenties*6+s.Tens)*4 + (j==null?0:j==Denomination.Fifty?1:j==Denomination.Twenty?2:3))*25 + Array.IndexOf(Amounts,a);
var T = new HashSet<int>();
