AccountState[] acc1 = [new(250, 0), new(250, 200), new(250, 190), new(250, 100), new(0, 0), new(5, 0), new(10, 0), new(100, 0), new(105, 0), new(110, 0), new(115, 0), new(205, 0), new(200, 10), new(55, 70)];
AccountState[] acc2 = [new(250, 0), new(115, 0), new(100, 50), new(0, 0), new(250, 190), new(205, 0)];
foreach (var s in AllStocks()) foreach (var j in Jams) foreach (var a in Amounts) foreach (var ac in acc1.Concat(acc2)) T.Add(Key(ac.Balance, ac.WithdrawnToday, s, j, a));
(NoteCounts, Denomination?)[] mods = [(new(5,5,5),null),(new(1,5,5),null),(new(0,0,0),null),(new(5,5,0),null),(new(5,5,5),Denomination.Fifty),(new(2,3,1),Denomination.Twenty),(new(4,1,5),Denomination.Ten)];
foreach (var (s,j) in mods) foreach (var a in Amounts) foreach (var b in Balances) foreach (var w in Withdrawns) T.Add(Key(b,w,s,j,a));
var R = new HashSet<int>();
for (int seed=1; seed<=8; seed++) { var random = new Random(seed);
  for (var run = 0; run < 50; run++) {
    var jam = Jams[random.Next(Jams.Length)];
    var stock = new NoteCounts(random.Next(6), random.Next(6), random.Next(6));
    var dispenser = new MoneyDispenser(stock, jam); var machine = new CashMachine(dispenser);
    var account = new AccountState(Balances[random.Next(Balances.Length)], Withdrawns[random.Next(Withdrawns.Length)]);
    for (var step = 0; step < 40; step++) {
      Operation op = random.Next(3) == 0 ? new Operation.Deposit(Deps[random.Next(8)]) : new Operation.Withdraw(Amounts[random.Next(Amounts.Length)]);
      if (op is Operation.Withdraw ww) R.Add(Key(account.Balance, account.WithdrawnToday, dispenser.Stock, jam, ww.Amount));
      var actual = machine.Execute(account, op);
      account = actual.Account;
      if (account.Balance > 250) account = account with { Balance = 250 };
      if (account.WithdrawnToday == 200 && random.Next(4) == 0) account = account with { WithdrawnToday = 0 };
    } } }
Console.WriteLine($"T={T.Count} R={R.Count}");
// predicates
var preds = new Dictionary<string, Func<int,int,NoteCounts,Denomination?,int,bool>>();
bool DailyOk(int w,int a)=> w+a<=200;
int Fee(int a)=> a>100?5:0;
bool Valid(int a)=> a>0&&a%10==0;
NoteCounts U(NoteCounts s, Denomination? j)=>Usable(s,j);
preds["feeShort&cannot"] = (b,w,s,j,a)=> Valid(a)&&DailyOk(w,a)&&b==a&&a>100&&Fewest(a,U(s,j))==null;
preds["feeShort&cannot&nonempty"] = (b,w,s,j,a)=> Valid(a)&&DailyOk(w,a)&&b==a&&a>100&&Fewest(a,U(s,j))==null&&U(s,j).Total>0;
preds["feeShort&cannot&nojam&nonempty"] = (b,w,s,j,a)=> Valid(a)&&DailyOk(w,a)&&b==a&&a>100&&Fewest(a,U(s,j))==null&&U(s,j).Total>0&&j==null;
preds["feeShort&cannot&fullOK"] = (b,w,s,j,a)=> Valid(a)&&DailyOk(w,a)&&b==a&&a>100&&Fewest(a,U(s,j))==null&&Fewest(a,s)!=null;
preds["feeShort&ok&multipass"] = (b,w,s,j,a)=> Valid(a)&&DailyOk(w,a)&&b==a&&a>100&&Fewest(a,U(s,j)) is {} n && n.Total>4;
preds["feeShort&ok&3pass"] = (b,w,s,j,a)=> Valid(a)&&DailyOk(w,a)&&b==a&&a>100&&Fewest(a,U(s,j)) is {} n && n.Total>8;
preds["feeShort&ok&alltens"] = (b,w,s,j,a)=> Valid(a)&&DailyOk(w,a)&&b==a&&a>100&&Fewest(a,U(s,j)) is {} n && n==U(s,j);
foreach (var (name, p) in preds) {
  long n=0, t=0, r=0;
  foreach (var s in AllStocks()) foreach (var j in Jams) foreach (var b in Balances) foreach (var w in Withdrawns) foreach (var a in Amounts)
    if (p(b,w,s,j,a)) { n++; var k=Key(b,w,s,j,a); if (T.Contains(k)) t++; if (R.Contains(k)) r++; }
  Console.WriteLine($"{name,-40} n={n,8} sweep={t,6} random={r,5}");
}
